"""Interactive full-arena budget and matched Energy interior comparisons."""
import argparse
import json
from pathlib import Path


def main():
    ap = argparse.ArgumentParser(description=__doc__); ap.add_argument('--out', type=Path, required=True); args = ap.parse_args(); out = args.out.resolve(); summary = json.loads((out / 'summary.json').read_bytes()); review = json.loads((out / 'review.json').read_bytes()); images = []
    for row in review['entries']: images.append({'id': row['id'], 'triangles': row['triangles'], 'images': {view: str(out / row['images'] / (view + '.webp')) for view in ['oblique', 'reverse', 'top', 'front', 'back', 'bottom', 'side']}})
    payload = {'groups': summary['groups'], 'components': summary['components'], 'totals': summary['totals'], 'images': images}
    html = '''<!doctype html><html><head><meta charset="utf-8"><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground,#222);margin:0}p{line-height:1.45;margin:0 0 12px}.muted,small{color:var(--muted-foreground,#666)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0 16px}.stats>div{border-top:2px solid var(--border,#ccc);padding-top:10px}.stats b{font-size:22px;display:block}table{width:100%;border-collapse:collapse;font-size:13px;margin:12px 0}td,th{text-align:right;border-bottom:1px solid var(--border,#ddd);padding:7px 4px}td:first-child,th:first-child{text-align:left}.bar{height:7px;border-radius:3px;background:var(--chart-1,#5687d3);margin:4px 0;width:var(--size)}.name{min-width:110px}.note{font-size:13px}.controls{display:grid;grid-template-columns:minmax(0,3fr) minmax(0,1fr);gap:12px;margin:18px 0 10px}label{display:block;font-size:13px}select{font:inherit;color:inherit;background:var(--background,white);border:1px solid var(--border,#ccc);padding:8px;border-radius:5px;max-width:100%}#labels{display:grid;grid-template-columns:1fr 1fr;text-align:center;font-size:13px;gap:6px;margin-bottom:6px}img{display:block;width:100%;height:auto;border-radius:6px}summary{cursor:pointer;margin:14px 0;font-size:14px}details table{font-size:12px}.wrap{overflow-x:auto}@media(max-width:480px){.stats b{font-size:18px}.controls{grid-template-columns:1fr}td,th{font-size:12px}}
</style></head><body>
<p><b>Complete arena · latest composed candidate</b><br><span class="muted">116 definitions · 171 source placements · 53.7 MB GLB</span></p>
<div class="stats"><div><b>1,307,799</b>placed visual triangles<br><small>instances counted</small></div><div><b>689,486</b>stored mesh triangles<br><small>shared meshes counted once</small></div><div><b>4.4%</b>groundwork / fixtures<br><small>equipment accounts for 95.6%</small></div></div>
<div class="wrap"><table><thead><tr><th>Group</th><th>Placed visual</th><th>Share</th><th>Collision budget*</th></tr></thead><tbody id="groups"></tbody><tfoot><tr><td><b>Total</b></td><td><b>1,307,799</b></td><td>100%</td><td><b>914,197*</b></td></tr></tfoot></table></div>
<p class="note"><b>Dart + Outpost = 52.6% of visual geometry.</b> Further floor reduction will have little impact on the whole map. Outpost housings and rotor modules are the largest remaining collision-budget target, followed by Tech Core.</p>
<p class="note muted">*Collision is a planning budget, not a runtime capture: 388,304 triangles come from dedicated candidates for 9 definitions; 525,893 still use visual fallback for 53 definitions. Another 54 whole markings contribute zero. Moving owners and scoring detectors still require binding. Tech Core and Rune remain fallback estimates.</p>
<details><summary>Individual definitions and collision coverage</summary><div class="controls"><label>Group<select id="group-filter"><option value="">All groups</option></select></label><label>Order<select id="order"><option value="visual_placed">Visual cost</option><option value="collision_budget_placed">Collision budget</option></select></label></div><div class="wrap"><table><thead><tr><th>Definition</th><th>Uses</th><th>Visual</th><th>Collision*</th><th>Method</th></tr></thead><tbody id="components"></tbody></table></div></details>
<p style="margin-top:22px"><b>Energy interior · rim-matched prism</b><br><span class="muted">The deep retainer changes from 1,744 to 84 triangles (−95.2%). Twelve placements save 19,920 visual triangles. The other 9,292 triangles per unit retain exact positions, normals, indices and materials.</span></p>
<div class="controls"><label>Scope<select id="part"></select></label><label>View<select id="view"><option>oblique</option><option>reverse</option><option>top</option><option>front</option><option>back</option><option>bottom</option><option>side</option></select></label></div><div id="labels"></div><img id="image" alt="Matched approved and prism interior views"><p class="note muted">The prism uses the original 22-vertex rim and material, extending 3 mm into the old retainer envelope. The bore and exterior stay unchanged. Collision remains the independent 1,056-triangle profile. These are inspection candidates; runtime assets remain unchanged.</p>
<script>const data=__DATA__,num=n=>n.toLocaleString(),total=data.totals.visual_placed;const groups=document.getElementById('groups');data.groups.forEach((r,i)=>{const tr=document.createElement('tr');const a=document.createElement('td');a.className='name';a.textContent=r.group;const bar=document.createElement('div');bar.className='bar';bar.style.setProperty('--size',(100*r.visual_placed/data.groups[0].visual_placed)+'%');bar.style.background=`var(--chart-${i%6+1},#5687d3)`;a.append(bar);tr.append(a);for(const v of [num(r.visual_placed),(100*r.visual_placed/total).toFixed(1)+'%',num(r.collision_budget_placed)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}groups.append(tr)});const filter=document.getElementById('group-filter'),order=document.getElementById('order');data.groups.forEach(r=>filter.add(new Option(r.group,r.group)));function list(){const table=document.getElementById('components');table.replaceChildren();data.components.filter(r=>!filter.value||r.group===filter.value).sort((a,b)=>b[order.value]-a[order.value]).forEach(r=>{const tr=document.createElement('tr');for(const v of [r.id,r.uses,num(r.visual_placed),num(r.collision_budget_placed),r.collision_method]){const td=document.createElement('td');td.textContent=v;tr.append(td)}table.append(tr)})}filter.onchange=order.onchange=list;list();const part=document.getElementById('part'),view=document.getElementById('view');data.images.forEach((r,i)=>part.add(new Option(r.id,i)));part.value=data.images.findIndex(r=>r.id==='retainer-only');view.value='reverse';function show(){const r=data.images[+part.value];document.getElementById('image').src=r.images[view.value];document.getElementById('labels').replaceChildren(...['reference','candidate'].map(s=>{const el=document.createElement('span');el.textContent=(s==='reference'?'Approved reference':'Interior prism')+' · '+num(r.triangles[s])+' tris';return el}))}part.onchange=view.onchange=show;show();</script></body></html>'''
    (out / 'review.html').write_text(html.replace('__DATA__', json.dumps(payload))); print(out / 'review.html')


if __name__ == '__main__': main()
